func TestOrderingAlphabeticalTiebreak(t *testing.T) {
	tests := []struct {
		name    string
		entries []Entry
		wantIDs []string
	}{
		{
			name: "score descending dominates",
			entries: []Entry{
				{ID: "a", DisplayName: "Alpha", Score: 500},
				{ID: "b", DisplayName: "Zulu", Score: 1000},
			},
			wantIDs: []string{"b", "a"},
		},
		{
			name: "equal scores fall to display name ascending",
			entries: []Entry{
				{ID: "x", DisplayName: "Волк", Score: 400},
				{ID: "y", DisplayName: "Атом", Score: 400},
			},
			wantIDs: []string{"y", "x"},
		},
		{
			name: "equal scores and names fall to id ascending",
			entries: []Entry{
				{ID: "dup-2", DisplayName: "Same", Score: 7},
				{ID: "dup-1", DisplayName: "Same", Score: 7},
			},
			wantIDs: []string{"dup-1", "dup-2"},
		},
		{
			name: "full chain: score, then name, then id",
			entries: []Entry{
				{ID: "1", DisplayName: "Mid", Score: 1000},
				{ID: "2", DisplayName: "Aaa", Score: 100},
				{ID: "3", DisplayName: "Zzz", Score: 100},
				{ID: "4", DisplayName: "Aaa", Score: 100},
			},
			wantIDs: []string{"1", "2", "4", "3"},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			Order(tt.entries)
			gotIDs := make([]string, 0, len(tt.entries))
			for _, e := range tt.entries {
				gotIDs = append(gotIDs, e.ID)
			}
			if !reflect.DeepEqual(gotIDs, tt.wantIDs) {
				t.Fatalf("Order gave %v, want %v", gotIDs, tt.wantIDs)
			}
		})
	}
}

func TestZeroInterestFloor(t *testing.T) {
	tests := []struct {
		name string
		e    EntityState
		w    Weights
		want float64
	}{
		{
			name: "no tags, no interest scores zero",
			e:    EntityState{},
			w:    nil,
			want: 0,
		},
		{
			name: "every tag is its base weight of one",
			e:    EntityState{Tags: []string{"action", "thriller", "drama"}},
			w:    nil,
			want: 3,
		},
		{
			name: "explicit zero interest equals the missing-key base",
			e:    EntityState{Tags: []string{"action", "thriller"}},
			w:    Weights{"action": 0, "thriller": 0},
			want: 2,
		},
		{
			name: "case variant tags still score one base each",
			e:    EntityState{Tags: []string{" Action ", "ACTION"}},
			w:    Weights{"action": 0},
			want: 2,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := Score(tt.e, tt.w); got != tt.want {
				t.Fatalf("Score(%+v) = %v, want %v", tt.e, got, tt.want)
			}
		})
	}
	// Zero interest degrades to the alphabetical floor: with every entity
	// carrying an equal tag count, Order falls to display name ascending.
	grid := []Entry{
		{ID: "1", DisplayName: "Бета", Score: Score(EntityState{Tags: []string{"a"}}, nil)},
		{ID: "2", DisplayName: "Альфа", Score: Score(EntityState{Tags: []string{"b"}}, nil)},
	}
	Order(grid)
	if grid[0].DisplayName != "Альфа" || !reflect.DeepEqual(
		[]float64{grid[0].Score, grid[1].Score}, []float64{1, 1}) {
		t.Fatalf("zero-interest grid not alphabetical at equal tag counts: %+v", grid)
	}
	if math.Abs(grid[1].Score-1) > 1e-9 {
		t.Errorf("base tag weight drifted: %v, want 1", grid[1].Score)
	}
}
